import openpyxl
ws=openpyxl.load_workbook('/workspace/input.xlsx').active
sections=[(40,42,67),(70,71,76),(79,82,89)]
for r0,r1,r2 in sections:
    print('\nRows',r0,'-' ,r2)
    for r in range(r1,r2+1):
        cells=[]
        for col in ['D','E','F','G','H','I','J','K','L','M','N','O']:
            c=ws[col+str(r)]
            if c.value is None:
                cells.append(col+':BLANK')
            else:
                cells.append(f"{col}:{('F' if c.data_type=='f' else 'V')}")
        print(f'{r:3}', ' '.join(cells))
print('Also economic blanks')
for row in range(24,30):
    print(row, [(c.coordinate, c.value) for c in ws[row] if c.coordinate[0] in ['C','D'] and c.coordinate[1:]==str(row)])
